window.game = {"title":"The Last Season","author":"Yuchen Wang","content":"","scenes":{"prevScene":{"id":"prevScene","content":{"content":"","type":"paragraph"}},"prevTopScene":{"id":"prevTopScene","content":{"content":"","type":"paragraph"}},"jumpScene":{"id":"jumpScene","content":{"content":"","type":"paragraph"}},"backSpecialScene":{"id":"backSpecialScene","content":{"content":"","type":"paragraph"}},"returnScene":{"id":"returnScene","content":{"content":"","type":"paragraph"}},"root.speech_result":{"id":"root.speech_result","title":"About Last Year","options":[{"id":"@root.choice1_easy","title":"\"As long as we maintain this level, we're sure to climb even higher this year.\""},{"id":"@root.choice1_serious","title":"\"But we cannot let this make us complacent. We need to keep training hard.\""}],"content":[{"type":"paragraph","content":"\"Last semester, we placed third in the autumn league.\""},{"type":"paragraph","content":"I paused, letting those words settle in the air for a moment."},{"type":"paragraph","content":"\"That result proves what this team is capable of. This year, I believe we can go even further.\""},{"type":"paragraph","content":"I scanned the faces in front of me and continued."}]},"daily_training.choice_ignore":{"id":"daily_training.choice_ignore","title":"They know what they are doing","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@captain_talk","title":"Training ended. A few days passed."}],"content":[{"type":"paragraph","content":"I turned away and said nothing."},{"type":"paragraph","content":"They did not notice my glance. The laughter continued."},{"type":"paragraph","content":"When practice ended, I watched them leave together, still talking and smiling. I stood on the field as they disappeared through the gate and did not think much of it."}]},"captain_talk.choice_agree":{"id":"captain_talk.choice_agree","title":"Sure, no problem","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@pitcher_solo","title":"Continue"}],"content":[{"type":"paragraph","content":"\"Sure, no problem. We have the seniors to back us up anyway.\""},{"type":"paragraph","content":"The tension went out of her shoulders. She nodded, looking relieved, like she had gotten the answer she was hoping for."},{"type":"paragraph","content":"\"Great, let's go with that then.\" She smiled."},{"type":"paragraph","content":"I nodded back. With the seniors on the team, what could really go wrong?"}]},"pitcher_solo.choice_straightforward":{"id":"pitcher_solo.choice_straightforward","title":"I'll go ask her","onArrival":[{"$code":"Q['pitcher_solo_aware'] = 0;"}],"options":[{"id":"@pitcher_talk","title":"She was still throwing when I reached her."}],"content":[{"type":"paragraph","content":"\"I think you're right. I'll go ask her.\""},{"type":"paragraph","content":"The senior smiled and said nothing more. I handed her my clipboard and walked across the field."}]},"pitcher_talk.choice_give_up":{"id":"pitcher_talk.choice_give_up","title":"Alright, I'll find someone else","options":[{"id":"@group_stage","title":"The weeks that followed"}],"content":[{"type":"paragraph","content":"\"Alright. I'll find someone else.\""},{"type":"paragraph","content":"She nodded quickly, looking almost relieved. I turned and walked back across the field."},{"type":"paragraph","content":"Something felt unfinished, but I let it go."}]},"group_stage":{"id":"group_stage","type":"scene","title":"The Group Stage","newPage":true,"goTo":[{"id":"group_stage_highlight"}],"content":[{"type":"paragraph","content":"We won every match in the group stage."},{"type":"paragraph","content":"It sounds simple when I say it like that, but it did not feel simple at the time. Each game had its own moments of tension, its own small crises that got resolved — a shaky inning steadied by a good play, a slow start that turned around in the third. We were not perfect. But we were consistent, and we found ways to pull through."},{"type":"paragraph","content":"By the time the final group stage result came in, we had earned our place in the knockout rounds. All of us."},{"type":"paragraph","content":"I watched the team celebrate on the field after the last group game. They were laughing and shouting, grabbing each other by the shoulders. The seniors were right there in the middle of it."},{"type":"paragraph","content":"I stood at the edge and let myself feel it for a moment. We had worked for this."}]},"group_stage_highlight.choice_relax":{"id":"group_stage_highlight.choice_relax","title":"This team is something else","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@senior_moment","title":"After the match"}],"content":[{"type":"paragraph","content":"I clapped along and laughed with the others on the bench. Someone said \"we've got this in the bag\" and I did not disagree."},{"type":"paragraph","content":"For a little while, I stopped watching the field as closely as I should have."}]},"senior_moment.choice_celebrate":{"id":"senior_moment.choice_celebrate","title":"Let's celebrate","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 2;"}],"options":[{"id":"@pre_quarterfinal","title":"The following week"}],"content":[{"type":"paragraph","content":"\"Absolutely. Let's do it.\""},{"type":"paragraph","content":"Her face lit up. Within minutes she had rallied everyone together, and we ended up at a restaurant nearby, a long table full of noise and laughter. Someone ordered too much food. Someone else made a speech that went on too long and was interrupted by clapping halfway through."},{"type":"paragraph","content":"I sat at the end of the table and let myself relax completely. We had earned this, I thought. And we were going to keep winning."}]},"pre_quarterfinal.choice_easy":{"id":"pre_quarterfinal.choice_easy","title":"They are not that strong","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@match_opening","title":"First pitch"}],"content":[{"type":"paragraph","content":"\"Today's opponent is East Asian Languages. They're not the strongest team in the tournament. Go out there and play your game.\""},{"type":"paragraph","content":"A few people nodded. Someone exhaled like they had been holding their breath and didn't need to anymore. The mood loosened."},{"type":"paragraph","content":"I told myself that was a good thing."}]},"match_opening.choice_let_it_go":{"id":"match_opening.choice_let_it_go","title":"She is probably right","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@match_opening.match_continue","title":"Third inning"}],"content":[{"type":"paragraph","content":"I said nothing. Honestly, I was thinking something similar."},{"type":"paragraph","content":"I leaned back against the fence and watched the next at-bat with less focus than I should have."}]},"errors_begin":{"id":"errors_begin","type":"scene","title":"The Turning Point","newPage":true,"goTo":[{"id":"match_tension"}],"content":[{"type":"paragraph","content":"Then the fourth inning came, and something shifted."},{"type":"paragraph","content":"It started with two errors — small ones, the kind that happen. Two runs scored. The score moved to five to two."},{"type":"paragraph","content":"The senior pitcher called out from the mound after the first one. \"It's fine, shake it off!\" Her voice was steady. Trying to hold things together."},{"type":"paragraph","content":"Ying said something to the player beside her — I couldn't hear what, but I saw the other girl nod."},{"type":"paragraph","content":"We were still leading. Three runs. It wasn't over."},{"type":"paragraph","content":"But I had been in enough games to know what the next few minutes were going to feel like."},{"type":"paragraph","content":"The captain appeared beside me. She didn't say anything. She just stood there, watching the field with the particular stillness of someone who doesn't know what to do but knows something needs to be done."},{"type":"paragraph","content":"I called timeout."}]},"match_tension.choice_wave_off":{"id":"match_tension.choice_wave_off","title":"We are still leading","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@critical_moment","title":"The score keeps changing"}],"content":[{"type":"paragraph","content":"\"Shake it off!\" I called out from the sideline."},{"type":"paragraph","content":"A few people glanced over. Nobody looked reassured."},{"type":"paragraph","content":"I told myself one run was still a lead. I told myself we had this."}]},"critical_moment.decision_pitcher":{"id":"critical_moment.decision_pitcher","title":"Put in Ying.","viewIf":{"$code":"return ((Q['comforted_pitcher'] || 0)===1);"},"options":[{"id":"@match_result","title":"The final innings"}],"content":[{"type":"paragraph","content":"She had said she could do it, and I believed her."},{"type":"paragraph","content":"\"You're in,\" I said."},{"type":"paragraph","content":"The substitute stepped back without argument. Ying rolled her shoulders once and walked toward the mound."}]},"match_result.win_result":{"id":"match_result.win_result","title":"We held on","viewIf":{"$code":"return ((Q['overconfident'] || 0) <= 4);"},"options":[{"id":"@celebration","title":"Celebrate"}],"content":{"content":[{"type":"paragraph","content":"When the last out was called, the score was six to four. We had won."},{"type":"paragraph","content":"For a moment nobody moved. Then someone screamed and the bench emptied onto the field."},{"type":"paragraph","content":{"type":"conditional","content":"I looked for Ying in the crowd.","predicate":0}}],"stateDependencies":[{"type":"predicate","fn":{"$code":"return ((Q['comforted_pitcher'] || 0)===1);"}}]}},"celebration.choice_thanks":{"id":"celebration.choice_thanks","title":"Thank the seniors","options":[{"id":"@good_ending_base","title":"Continue"}],"content":{"content":[{"type":"paragraph","content":"I stepped forward."},{"type":"paragraph","content":"\"I want to say something,\" I said. Everyone turned to look at me."},{"type":"paragraph","content":"\"This season would not have been what it was without the seniors. Everything you brought to this team — your experience, your patience, the way you showed up every single week — that's what made today possible.\""},{"type":"paragraph","content":"One of the seniors wiped her eyes. Another looked at the ground."},{"type":"paragraph","content":"\"Thank you,\" I said. \"Genuinely. Thank you.\""},{"type":"paragraph","content":{"type":"conditional","content":"I looked for Ying in the crowd. She was standing a little apart from the others, watching. When she caught my eye, she gave a small nod.","predicate":0}}],"stateDependencies":[{"type":"predicate","fn":{"$code":"return ((Q['comforted_pitcher'] || 0)===1);"}}]}},"aftermath.choice_complain":{"id":"aftermath.choice_complain","title":"Say what I am thinking","options":[{"id":"@confrontation","title":"It was not the end of it."}],"content":[{"type":"paragraph","content":"I found the captain before she got too far."},{"type":"paragraph","content":"I kept my voice low. I told her what I thought — about the mistakes, about the players who had let us down, about how this should not have happened."},{"type":"paragraph","content":"She listened. She did not say much."},{"type":"paragraph","content":"I thought that was the end of it."}]},"confrontation.choice_apologize":{"id":"confrontation.choice_apologize","title":"Let me try again","options":[{"id":"@argument","title":"What happened next"}],"content":[{"type":"paragraph","content":"I held up a hand."},{"type":"paragraph","content":"\"That came out wrong,\" I said. \"I was angry. I still am. But I should not have said it the way I did.\""},{"type":"paragraph","content":"She looked at me for a long moment."},{"type":"paragraph","content":"\"But you meant it.\""},{"type":"paragraph","content":"I didn't answer. Which was, of course, an answer."}]},"argument.breakup":{"id":"argument.breakup","title":"The End","gameOver":true,"content":[{"type":"paragraph","content":"I do not know exactly when it happened — whether it was that day or gradually after — but something closed between us. We still saw each other at practice. We still existed in the same spaces. We just stopped being people who talked to each other."},{"type":"paragraph","content":"The ones I had coached all season. The seniors in their last year. The girl I had stood beside on a hundred ordinary afternoons."},{"type":"paragraph","content":"We passed each other in the hallway and looked straight ahead."},{"type":"paragraph","content":"Some endings are not dramatic. They are just quiet, and permanent."}]},"argument":{"id":"argument","type":"scene","title":"The Fight","newPage":true,"options":[{"id":"@argument.breakup","title":"Continue"}],"content":{"content":[{"type":"paragraph","content":"It escalated quickly."},{"type":"paragraph","content":"One of them said something sharp. I said something sharper back. The one who had spoken first stepped forward, her voice rising. Someone behind her said my name like it was an accusation."},{"type":"paragraph","content":"I do not remember the exact words. I remember the feeling — that particular combination of righteousness and regret that comes from saying true things at the wrong time in the wrong way."},{"type":"paragraph","content":"At some point it stopped being a conversation and became something else."},{"type":"paragraph","content":[{"type":"conditional","content":"I thought I saw Ying at the edge of the group, watching. She did not say anything. She just looked at me with an expression I could not read, and then she turned and walked away. ","predicate":0},""]},{"type":"paragraph","content":"Eventually the words ran out."},{"type":"paragraph","content":"There was a silence. Then one of them said they were sorry they had not played better. I said I was sorry for what I had said to the captain. It was the kind of apology that covers the surface of something without touching what is underneath."},{"type":"paragraph","content":"We nodded at each other. And that was that."}],"stateDependencies":[{"type":"predicate","fn":{"$code":"return ((Q['comforted_pitcher'] || 0)===1);"}}]}},"neutral_ending.neutral_ending_close":{"id":"neutral_ending.neutral_ending_close","title":"The End","gameOver":true,"content":[{"type":"paragraph","content":"But sometimes, carrying something is enough."},{"type":"paragraph","content":"That was the year I learned that."}]},"neutral_ending":{"id":"neutral_ending","type":"scene","title":"The Next Day","newPage":true,"options":[{"id":"@neutral_ending.neutral_ending_close","title":"Continue"}],"content":[{"type":"paragraph","content":"I did not sleep well."},{"type":"paragraph","content":"I lay awake going over the match in my head — the early innings when everything felt easy, the moment the errors started, the final out. I kept looking for the exact place where it had gone wrong. I never found one. It had gone wrong everywhere, a little at a time, and then all at once."},{"type":"paragraph","content":"The next morning I got to the field before anyone else."},{"type":"paragraph","content":"I stood there in the early quiet and thought about what I wanted to say. Not to defend myself. Not to assign blame. Just to say what was true."},{"type":"paragraph","content":"When the team arrived, I waited for everyone to gather. Then I stepped forward."},{"type":"paragraph","content":"\"Yesterday was hard,\" I said. \"We had it and we lost it. That happens in sport. It happened to us yesterday.\""},{"type":"paragraph","content":"I paused."},{"type":"paragraph","content":"\"Some of that was on the players. Some of it was on me. I let us get comfortable when we should have stayed sharp. I should have managed that better. I did not.\""},{"type":"paragraph","content":"Nobody said anything. A few people were looking at the ground."},{"type":"paragraph","content":"\"We are not done,\" I said. \"But today I just wanted to say that. Whatever comes next — that one is on me.\""},{"type":"paragraph","content":"I stepped back."},{"type":"paragraph","content":"Practice began a few minutes later. Nobody brought it up again."},{"type":"paragraph","content":"Some things do not get resolved. They just get carried."}]},"good_ending_base":{"id":"good_ending_base","type":"scene","title":"A Good Day","newPage":true,"gameOver":true,"content":{"content":[{"type":"paragraph","content":"Later, after everyone had gone, I stood on the empty field for a while."},{"type":"paragraph","content":"We had won. The seniors were leaving. Both things were true at the same time, and I let myself feel both of them."},{"type":"paragraph","content":"It had been a good season. Not a perfect one — there were things I would have done differently, moments I wished had gone another way."},{"type":"paragraph","content":[{"type":"conditional","content":"I thought about Ying. The way she had looked at me when I caught her eye in the crowd. I had wanted to go over. I didn't. Some things you let pass, and you carry them quietly. ","predicate":0},""]},{"type":"paragraph","content":"But today was good."},{"type":"paragraph","content":"That was enough."}],"stateDependencies":[{"type":"predicate","fn":{"$code":"return ((Q['comforted_pitcher'] || 0)===1);"}}]}},"good_ending_full":{"id":"good_ending_full","type":"scene","title":"What I Said to Ying","newPage":true,"gameOver":true,"content":[{"type":"paragraph","content":"I found Ying near the edge of the field, a little away from the others."},{"type":"paragraph","content":"She heard me coming and turned around."},{"type":"paragraph","content":"\"You did it,\" I said."},{"type":"paragraph","content":"She looked down for a second. \"We did it,\" she said."},{"type":"paragraph","content":"I stood there for a moment. Then I said the thing I had been thinking for a while — the thing I had not planned to say out loud until it was already coming out."},{"type":"paragraph","content":"She went quiet."},{"type":"paragraph","content":"Then she looked up at me. Not quite smiling, but close."},{"type":"paragraph","content":"\"I need to think about it,\" she said. \"But I'm glad you told me.\""},{"type":"paragraph","content":"It wasn't a yes. But it wasn't a no either."},{"type":"paragraph","content":"I walked home in the last of the evening light, thinking about the season, about the game, about the look on her face when I said what I said."},{"type":"paragraph","content":"Some things don't resolve cleanly. But some things don't need to."}]},"root.choice1_easy":{"id":"root.choice1_easy","title":"Just maintain the level","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@root.choice2_rely","title":"\"Our seniors are strong. I'm confident we'll be fine.\""},{"id":"@root.choice2_cherish","title":"\"I hope everyone will learn from them. Let's give the seniors the best farewell we can.\""}],"content":[{"type":"paragraph","content":"\"As long as we maintain this level, we're sure to climb even higher this year.\""},{"type":"paragraph","content":"A few heads nodded. Someone laughed softly. The mood lifted almost immediately."},{"type":"paragraph","content":"Then I turned toward the back row."},{"type":"paragraph","content":"\"This year, we have several fourth-year players. This will be their last autumn league.\""},{"type":"paragraph","content":"The field went quiet for a moment. Even the ones who usually had something to say stayed silent."}]},"daily_training.choice_remind":{"id":"daily_training.choice_remind","title":"Go remind them","options":[{"id":"@captain_talk","title":"Training ended. A few days passed."}],"content":[{"type":"paragraph","content":"I walked over and stopped beside them."},{"type":"paragraph","content":"Both of them looked up. The smiles faded."},{"type":"paragraph","content":"\"Focus,\" I said. Just the one word."},{"type":"paragraph","content":"They nodded and tightened their grip on their bats. I stayed nearby for a moment until I was sure they had actually started working, then moved on."}]},"daily_training":{"id":"daily_training","type":"scene","title":"Daily Training","newPage":true,"options":[{"id":"@daily_training.choice_ignore","title":"They are experienced players. They know what they are doing. No need to say anything."},{"id":"@daily_training.choice_remind","title":"Walk over and remind them to focus."}],"content":[{"type":"paragraph","content":"Training was repetitive, but there was something grounding about the routine."},{"type":"paragraph","content":"In those weeks, we met on the same field every few days, running through the same motions: warm-up, drills, group practice, cooldown. Everyone knew their role. The rhythm slowly settled into something comfortable."},{"type":"paragraph","content":"Then one afternoon, about halfway through practice, I noticed something off."},{"type":"paragraph","content":"Two players were standing near the edge of the field. Their bats sat idle in their hands. They were whispering something to each other, laughing quietly, completely checked out. I recognized them both — veterans who had been on the team for two years."}]},"captain_talk.choice_careful":{"id":"captain_talk.choice_careful","title":"Winning comes first","options":[{"id":"@pitcher_solo","title":"Continue"}],"content":[{"type":"paragraph","content":"\"I hear you. If we are ahead by enough in a game, I will consider rotating them in — but winning has to come first.\""},{"type":"paragraph","content":"She paused, then slowly nodded."},{"type":"paragraph","content":"\"You're right,\" she said. \"Let's play it by ear then.\""},{"type":"paragraph","content":"She lingered for a second, as if she wanted to add something, then thought better of it and walked away."}]},"captain_talk":{"id":"captain_talk","type":"scene","title":"A Talk with the Captain","newPage":true,"options":[{"id":"@captain_talk.choice_agree","title":"\"Sure, no problem. We have the seniors to back us up anyway.\""},{"id":"@captain_talk.choice_careful","title":"\"I hear you. If we are ahead by enough in a game, I will consider rotating them in. But winning has to come first.\""}],"content":[{"type":"paragraph","content":"A few days later, the captain came to find me."},{"type":"paragraph","content":"The team captain was new this semester — same year as me, never been captain before."},{"type":"paragraph","content":"She was earnest and took things seriously, but sometimes she got ahead of herself. That was fine. Most first-timers did."},{"type":"paragraph","content":"She found me just before the end of one practice and said she had something she wanted to discuss."},{"type":"paragraph","content":"She told me she thought we should let some of the first and second year players take the field this season — give them a chance to experience real competition. She laid it out carefully, like she had been thinking about it for a while."},{"type":"paragraph","content":"\"What do you think?\" she asked, looking up at me."}]},"pitcher_solo.choice_observant":{"id":"pitcher_solo.choice_observant","title":"She seems unsure","onArrival":[{"$code":"Q['pitcher_solo_aware'] = 1;"}],"options":[{"id":"@pitcher_talk","title":"She was still throwing when I reached her."}],"content":[{"type":"paragraph","content":"\"She looks a little unsure of herself. I'll go talk to her and see.\""},{"type":"paragraph","content":"The senior glanced at me, then back at the girl. \"She just needs someone to believe in her,\" she said quietly."},{"type":"paragraph","content":"I nodded and started walking across the field."}]},"pitcher_solo":{"id":"pitcher_solo","type":"scene","title":"Watching from a Distance","newPage":true,"options":[{"id":"@pitcher_solo.choice_straightforward","title":"\"I think you're right. I'll go ask her.\""},{"id":"@pitcher_solo.choice_observant","title":"\"She looks a little unsure of herself. I'll go talk to her and see.\""}],"content":[{"type":"paragraph","content":"That same evening, practice had ended. Players were packing up their bags, calling out goodbyes, drifting toward the gate in twos and threes."},{"type":"paragraph","content":"I was still standing on the field when I noticed a figure in the far corner."},{"type":"paragraph","content":"It was a player from my own year. Her name was Ying. She had stayed behind. She stood alone near the wall, throwing the ball against it, catching it, throwing it again. Over and over, without stopping. There was something quiet and determined about the way she moved — no audience, no approval sought. Just her and the ball and the wall."},{"type":"paragraph","content":"I stood and watched for a while without saying anything."},{"type":"paragraph","content":"Then I heard footsteps beside me. One of the seniors had walked over. She followed my gaze toward the corner and was quiet for a moment."},{"type":"paragraph","content":"\"You've been watching her,\" she said. It wasn't really a question. \"She's been staying late a lot recently. She's got something.\" She paused. \"Have you thought about letting her start as pitcher this season?\""},{"type":"paragraph","content":"I looked at the girl in the corner. She still hadn't noticed us."}]},"pitcher_talk.choice_encourage":{"id":"pitcher_talk.choice_encourage","title":"I don't think that's really why","chooseIf":{"$code":"return ((Q['overconfident'] || 0) <= 4);"},"unavailableSubtitle":"You don't have the patience for this right now.","onDeparture":[{"$code":"Q['comforted_pitcher'] = 1;"}],"options":[{"id":"@group_stage","title":"The weeks that followed"}],"content":{"content":[{"type":"paragraph","content":[{"type":"conditional","content":"I had been watching her from across the field for a while before I came over. I knew what I was seeing. ","predicate":0},""]},{"type":"paragraph","content":"\"I don't think that's really why,\" I said."},{"type":"paragraph","content":"She looked up at me."},{"type":"paragraph","content":[{"type":"conditional","content":"\"I've seen you staying late. Every time. You've been putting in more work than anyone else on this team. I notice these things.\" I paused. \"I believe in you.\" ","predicate":1},""]},{"type":"paragraph","content":[{"type":"conditional","content":"\"You don't have to tell me everything. But I think you can do this. Will you at least tell me what's holding you back?\" ","predicate":2},""]},{"type":"paragraph","content":"She was quiet for a long moment. Then she looked down at the ball in her hand."},{"type":"paragraph","content":"\"I haven't really focused on pitching in a while,\" she said at last. \"Not properly. I'm scared I'll mess things up for the seniors. Their last season — I don't want to be the reason it goes wrong.\""},{"type":"paragraph","content":"I let her finish. Then I said:"},{"type":"paragraph","content":"\"You've already done the work. The rest is just believing it.\""},{"type":"paragraph","content":"She didn't say anything. But when she looked up, something in her face had shifted."}],"stateDependencies":[{"type":"predicate","fn":{"$code":"return ((Q['pitcher_solo_aware'] || 0)===1);"}},{"type":"predicate","fn":{"$code":"return ((Q['pitcher_solo_aware'] || 0)===1);"}},{"type":"predicate","fn":{"$code":"return ((Q['pitcher_solo_aware'] || 0)===0);"}}]}},"pitcher_talk":{"id":"pitcher_talk","type":"scene","title":"The Conversation","newPage":true,"options":[{"id":"@pitcher_talk.choice_give_up","title":"\"Alright. I'll find someone else.\""},{"id":"@pitcher_talk.choice_encourage","title":"\"I don't think that's really why.\""}],"content":{"content":[{"type":"paragraph","content":"She heard my footsteps and turned around. For a moment she just looked at me, a little surprised, the ball still in her hand."},{"type":"paragraph","content":"I told her that the senior and I had been talking, and that we wanted her to try starting as pitcher this season."},{"type":"paragraph","content":"She was quiet for a second. Then she shook her head."},{"type":"paragraph","content":"\"It's fine,\" she said. \"I just don't want to.\""},{"type":"paragraph","content":"I looked at her. She wasn't meeting my eyes. I knew that look — it wasn't reluctance. It was something closer to fear."},{"type":"paragraph","content":{"type":"conditional","content":"I had other things to figure out. I couldn't spend too much time on this.","predicate":0}}],"stateDependencies":[{"type":"predicate","fn":{"$code":"return ((Q['overconfident'] || 0) >= 5);"}}]}},"group_stage_highlight.choice_focus":{"id":"group_stage_highlight.choice_focus","title":"Keep the team focused","options":[{"id":"@senior_moment","title":"After the match"}],"content":[{"type":"paragraph","content":"I called out her name and raised my fist. She glanced over and nodded."},{"type":"paragraph","content":"Then I turned to the players waiting on the bench."},{"type":"paragraph","content":"\"You see that? Watch how she sets up before the pitch. Watch her feet.\" A few of them leaned forward. \"That's what we're working toward.\""}]},"group_stage_highlight":{"id":"group_stage_highlight","type":"scene","title":"A Moment to Remember","newPage":true,"options":[{"id":"@group_stage_highlight.choice_relax","title":"Join in the celebration. This team is something else."},{"id":"@group_stage_highlight.choice_focus","title":"Cheer for her, then turn back to the rest of the team."}],"content":[{"type":"paragraph","content":"One match stood out from the rest."},{"type":"paragraph","content":"It was the second group stage match. We were leading, but not comfortably."},{"type":"paragraph","content":"Then one of the seniors stepped up to bat."},{"type":"paragraph","content":"The pitch came in. She read it perfectly — shifted her weight, swung clean and level, and connected with a crack that cut right through the noise of the field. The ball sailed out into the gap. Two runners scored. Then a third."},{"type":"paragraph","content":"The bench erupted. People were on their feet, shouting her name."},{"type":"paragraph","content":"I stood at the sideline and watched her round the bases. She was smiling — not the wide, showy kind, but the quiet kind, the kind that meant something."}]},"senior_moment.choice_refuse":{"id":"senior_moment.choice_refuse","title":"The tournament is not over yet","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) - 1;"}],"options":[{"id":"@pre_quarterfinal","title":"The following week"}],"content":[{"type":"paragraph","content":"I shook my head."},{"type":"paragraph","content":"\"Not yet. We're still in the tournament. Save it for when we've actually won something.\""},{"type":"paragraph","content":"The captain blinked. For a moment she looked like she wanted to argue. Then she nodded slowly."},{"type":"paragraph","content":"\"Right,\" she said. \"Yeah. Okay.\""},{"type":"paragraph","content":"The others who had overheard went quiet for a second. Then someone picked up their bag and said \"same time Thursday then\" and just like that, people started heading home."},{"type":"paragraph","content":"I stayed behind until the field was empty. There was still work to do."}]},"senior_moment":{"id":"senior_moment","type":"scene","title":"After the Match","newPage":true,"options":[{"id":"@senior_moment.choice_celebrate","title":"\"Absolutely. Let's do it.\""},{"id":"@senior_moment.choice_refuse","title":"\"Not yet. The tournament isn't over.\""}],"content":[{"type":"paragraph","content":"The group stage was over. We had made it through."},{"type":"paragraph","content":"The captain came running over before I had even put down my clipboard. She was grinning."},{"type":"paragraph","content":"\"We should celebrate,\" she said. \"All of us together. Dinner somewhere — what do you think?\""},{"type":"paragraph","content":"I looked at her. Around us, players were still buzzing from the last match, talking loudly, not quite ready to leave."}]},"pre_quarterfinal.choice_serious":{"id":"pre_quarterfinal.choice_serious","title":"Play our best regardless","options":[{"id":"@match_opening","title":"First pitch"}],"content":[{"type":"paragraph","content":"\"This is a knockout match. It doesn't matter who's on the other side. We play our best, start to finish.\""},{"type":"paragraph","content":"Nobody said anything for a moment. Then the captain nodded, and a few others followed."},{"type":"paragraph","content":"\"Let's go,\" someone said quietly."}]},"pre_quarterfinal":{"id":"pre_quarterfinal","type":"scene","title":"Before the Quarterfinal","newPage":true,"options":[{"id":"@pre_quarterfinal.choice_easy","title":"\"Today's opponent is East Asian Languages. They're not the strongest team in the tournament. Go out there and play your game.\""},{"id":"@pre_quarterfinal.choice_serious","title":"\"This is a knockout match. It doesn't matter who's on the other side. We play our best, start to finish.\""}],"content":[{"type":"paragraph","content":"The quarterfinal draw came out. Our opponent was the East Asian Languages department."},{"type":"paragraph","content":"I had seen them play once during the group stage. They were not a strong team — slow to rotate, inconsistent pitching, a couple of good hitters but nothing that kept you up at night. On paper, this was a favorable draw."},{"type":"paragraph","content":"I gathered the team before the match. Everyone was already there when I arrived. I looked at their faces — some relaxed, some focused, some hard to read."},{"type":"paragraph","content":"I took a breath and spoke."}]},"match_opening.choice_stay_sharp":{"id":"match_opening.choice_stay_sharp","title":"Not done until it is done","options":[{"id":"@match_opening.match_continue","title":"Third inning"}],"content":[{"type":"paragraph","content":"I looked over at her."},{"type":"paragraph","content":"\"Not yet,\" I said. \"Stay in it.\""},{"type":"paragraph","content":"She straightened up and nodded. A couple of the others who had heard her glanced at me and then back at the field."},{"type":"paragraph","content":"I turned my attention back to the game."}]},"match_tension.choice_timeout":{"id":"match_tension.choice_timeout","title":"Call a second timeout","options":[{"id":"@critical_moment","title":"The score keeps changing"}],"content":[{"type":"paragraph","content":"I raised my hand and called timeout before the next pitch."},{"type":"paragraph","content":"They jogged over. I looked at each of them — the senior pitcher breathing hard, Ying still not looking up, the others somewhere between nervous and exhausted."},{"type":"paragraph","content":"I kept my voice low and even."},{"type":"paragraph","content":"\"What just happened is done. Tell me what you're seeing out there.\""},{"type":"paragraph","content":"Nobody spoke for a second. Then the senior pitcher said, \"Their cleanup batter is going to the opposite field. We've been throwing inside.\""},{"type":"paragraph","content":"I nodded. \"So we stop doing that. Ying — you good?\""},{"type":"paragraph","content":"She looked up. \"I'm good,\" she said."},{"type":"paragraph","content":"She didn't look good. But she said it like she meant it."}]},"match_tension":{"id":"match_tension","type":"scene","title":"First Timeout","newPage":true,"options":[{"id":"@match_tension.choice_wave_off","title":"Call out something encouraging and leave it at that. We are still leading."},{"id":"@match_tension.choice_timeout","title":"Call a second timeout. Get everyone focused again before this gets worse."}],"content":[{"type":"paragraph","content":"I gathered the infield quickly."},{"type":"paragraph","content":"\"Reset,\" I said. \"Three-run lead. We are still in control of this game. Play your positions, trust each other, one pitch at a time.\""},{"type":"paragraph","content":"The senior pitcher nodded. Ying was looking at the ground. The others listened."},{"type":"paragraph","content":"They went back out."},{"type":"paragraph","content":"For a moment, it seemed to work. The next batter grounded out. Someone on our bench exhaled."},{"type":"paragraph","content":"Then the fifth inning started, and it fell apart again."},{"type":"paragraph","content":"Two more errors. The other team scored twice more. Five to four."},{"type":"paragraph","content":"The senior's voice cracked this time. \"Come on!\" she said — not calm anymore, not encouraging. Just sharp and tired and scared."},{"type":"paragraph","content":"And then Ying. A ground ball, fielded cleanly. The throw to second — it went wide. The runner advanced."},{"type":"paragraph","content":"Ying stood in the infield with her glove at her side. She didn't look up."},{"type":"paragraph","content":"I had been watching the game. Now I was watching my team."},{"type":"paragraph","content":"The question was what I was going to do about it."}]},"critical_moment.decision_pitcher_unconfident":{"id":"critical_moment.decision_pitcher_unconfident","title":"Put in Ying.","viewIf":{"$code":"return ((Q['comforted_pitcher'] || 0)===0);"},"onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@match_result","title":"The final innings"}],"content":[{"type":"paragraph","content":"She did not look confident. But I put her in anyway."},{"type":"paragraph","content":"I nodded and told the substitute to sit back down."},{"type":"paragraph","content":"Ying walked to the mound without a word."}]},"match_result.lose_result":{"id":"match_result.lose_result","title":"It slipped away","viewIf":{"$code":"return ((Q['overconfident'] || 0) >= 5);"},"options":[{"id":"@aftermath","title":"After the match"}],"content":[{"type":"paragraph","content":"By the time the last out was called the score had flipped. They had taken the lead and held it."},{"type":"paragraph","content":"We lost."},{"type":"paragraph","content":"I stood at the sideline as the other team celebrated. Our players drifted off the field in ones and twos, quiet, not looking at each other."}]},"match_result":{"id":"match_result","type":"scene","title":"The Final Innings","newPage":true,"options":[{"id":"@match_result.win_result","title":"Continue"},{"id":"@match_result.lose_result","title":"Continue"}],"content":{"content":[{"type":"paragraph","content":"The substitution was made. Play resumed."},{"type":"paragraph","content":"The final innings were tense. Every pitch felt heavier than the last."},{"type":"paragraph","content":[{"type":"conditional","content":"We held on. The substitute found her rhythm, and our batters came through when it mattered. ","predicate":0}," ",{"type":"conditional","content":"The momentum never came back. The other team kept pushing, and we could not stop them.","predicate":1}]}],"stateDependencies":[{"type":"predicate","fn":{"$code":"return ((Q['overconfident'] || 0) <= 4);"}},{"type":"predicate","fn":{"$code":"return ((Q['overconfident'] || 0) >= 5);"}}]}},"celebration.choice_future":{"id":"celebration.choice_future","title":"Tell them this doesn't have to be goodbye","options":[{"id":"@good_ending_full","title":"Continue"}],"content":{"content":[{"type":"paragraph","content":"I stepped forward."},{"type":"paragraph","content":"\"Hey,\" I said. \"Listen to me.\""},{"type":"paragraph","content":"They looked up."},{"type":"paragraph","content":"\"Graduation isn't the end. If you want to come back on a weekend and play, come back. This field isn't going anywhere. We're not going anywhere.\" I paused. \"You're always going to be part of this team. That doesn't stop when you get your diploma.\""},{"type":"paragraph","content":"Someone laughed softly. One of the seniors reached out and grabbed my arm for a second."},{"type":"paragraph","content":{"type":"conditional","content":"I looked for Ying in the crowd. She was already looking at me.","predicate":0}}],"stateDependencies":[{"type":"predicate","fn":{"$code":"return ((Q['comforted_pitcher'] || 0)===1);"}}]}},"celebration":{"id":"celebration","type":"scene","title":"We Won","newPage":true,"options":[{"id":"@celebration.choice_thanks","title":"Thank the seniors for everything they gave this team."},{"id":"@celebration.choice_future","title":"Tell them this doesn't have to be goodbye."}],"content":[{"type":"paragraph","content":"The bench emptied onto the field. Players were grabbing each other, shouting, jumping. The seniors were right in the middle of it — laughing, some of them crying, holding on to each other like they didn't want to let go."},{"type":"paragraph","content":"I stood at the edge and watched. Something in my chest felt loose and warm."},{"type":"paragraph","content":"Then I noticed one of the seniors had stopped moving. She was standing still in the middle of all the noise, and she was crying — not the kind from excitement, but the other kind. The quiet kind."},{"type":"paragraph","content":"Someone asked her what was wrong."},{"type":"paragraph","content":"She shook her head and laughed a little through the tears."},{"type":"paragraph","content":"\"Nothing's wrong,\" she said. \"It's just — this is the last time. We're graduating. This is the last time I get to play with everyone.\""},{"type":"paragraph","content":"The noise around her softened. Someone else started crying. Then another."},{"type":"paragraph","content":"For a moment, the whole field went quiet in a different way."},{"type":"paragraph","content":"I looked at all of them — the seniors, the juniors, the first-years who had only known this team for a few months. Everyone standing together in the late afternoon light."}]},"aftermath.choice_stay_silent":{"id":"aftermath.choice_stay_silent","title":"Take a breath. Walk away.","chooseIf":{"$code":"return ((Q['overconfident'] || 0) <= 7);"},"unavailableSubtitle":"You are not ready to let this go yet.","options":[{"id":"@neutral_ending","title":"The next day"}],"content":[{"type":"paragraph","content":"I stood there for another minute. Then I picked up my bag and started walking."},{"type":"paragraph","content":"There was nothing useful left to say tonight. Maybe there never was."}]},"aftermath":{"id":"aftermath","type":"scene","title":"After the Match","newPage":true,"options":[{"id":"@aftermath.choice_complain","title":"Find the captain and say what I am thinking."},{"id":"@aftermath.choice_stay_silent","title":"Take a breath. Say nothing. Walk away."}],"content":[{"type":"paragraph","content":"The other team was still celebrating when I walked off the field."},{"type":"paragraph","content":"I found a spot near the fence and stood there for a while. The noise from the other side of the field felt very far away."},{"type":"paragraph","content":"The captain found me a few minutes later. She looked like she had been crying, or was about to. She said something — I am not sure what, exactly. Something about how we played well, how it wasn't anyone's fault."},{"type":"paragraph","content":"I nodded. I heard the words. I just wasn't really listening."},{"type":"paragraph","content":"After she walked away, I stood there alone."},{"type":"paragraph","content":"We had been winning. We had been so far ahead. And then —"},{"type":"paragraph","content":"The anger came quietly at first, and then all at once. I knew whose mistakes had cost us. I knew exactly which plays, which moments, which failures had added up to this."}]},"confrontation.choice_stand_firm":{"id":"confrontation.choice_stand_firm","title":"I meant every word","options":[{"id":"@argument","title":"What happened next"}],"content":[{"type":"paragraph","content":"\"Those were critical mistakes,\" I said. \"In a match we should have won. I stand by what I said.\""},{"type":"paragraph","content":"The silence that followed was the kind that does not end well."}]},"confrontation":{"id":"confrontation","type":"scene","title":"They Found Out","newPage":true,"options":[{"id":"@confrontation.choice_apologize","title":"Wait. That came out wrong. Let me try again."},{"id":"@confrontation.choice_stand_firm","title":"I meant every word."}],"content":[{"type":"paragraph","content":"I thought my conversation with the captain had stayed between us."},{"type":"paragraph","content":"It did not."},{"type":"paragraph","content":"I am not sure how it got out — whether she told someone, or someone overheard, or it simply spread the way things do in a team that has been together long enough. But by the next practice, they knew."},{"type":"paragraph","content":"Three of them came to find me together. The ones I had spoken about. They stood in front of me with the particular stillness of people who have decided to say something difficult and have been rehearsing it."},{"type":"paragraph","content":"The one who had made the most critical error spoke first."},{"type":"paragraph","content":"\"We heard what you said.\""},{"type":"paragraph","content":"I looked at her. I did not deny it."},{"type":"paragraph","content":"\"I said what I thought,\" I told her. \"I still think it.\""},{"type":"paragraph","content":"That was probably the wrong thing to say."}]},"root.choice1_serious":{"id":"root.choice1_serious","title":"No room for complacency","options":[{"id":"@root.choice2_rely","title":"\"Our seniors are strong. I'm confident we'll be fine.\""},{"id":"@root.choice2_cherish","title":"\"I hope everyone will learn from them. Let's give the seniors the best farewell we can.\""}],"content":[{"type":"paragraph","content":"\"But we cannot let this make us complacent. We need to keep training hard.\""},{"type":"paragraph","content":"The expressions around me grew a little more focused. A few of the newer players exchanged glances."},{"type":"paragraph","content":"Then I turned toward the back row."},{"type":"paragraph","content":"\"This year, we have several fourth-year players. This will be their last autumn league.\""},{"type":"paragraph","content":"The field went quiet for a moment. Even the ones who usually had something to say stayed silent."}]},"match_opening.match_continue":{"id":"match_opening.match_continue","title":"Third Inning","options":[{"id":"@match_opening.choice_comfortable","title":"Let yourself relax. You've earned this lead."},{"id":"@match_opening.choice_watchful","title":"Keep your eyes on everything. Stay sharp."}],"content":[{"type":"paragraph","content":"By the third inning we were still leading. A clean catch ended their half of the inning and someone on our bench let out a whoop."},{"type":"paragraph","content":"I watched our next batter walk to the plate."}]},"critical_moment.decision_substitute":{"id":"critical_moment.decision_substitute","title":"Put in the substitute.","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@match_result","title":"The final innings"}],"content":[{"type":"paragraph","content":"I turned to the substitute."},{"type":"paragraph","content":"\"You're in.\""},{"type":"paragraph","content":"She nodded and moved toward the mound. Ying said nothing. She walked back to the bench and sat down without looking at anyone."}]},"critical_moment":{"id":"critical_moment","type":"scene","title":"The Decision","newPage":true,"options":[{"id":"@critical_moment.decision_pitcher","title":"Put in Ying."},{"id":"@critical_moment.decision_substitute","title":"Put in the substitute."}],"content":{"content":[{"type":"paragraph","content":"Five to four. One run."},{"type":"paragraph","content":"I waved over two players — Ying, and one of the younger substitutes. They jogged over and stood in front of me. The senior pitcher was still on the mound, but I could see it in her shoulders. She was running out."},{"type":"paragraph","content":"\"We need someone to step in,\" I said. \"Give the seniors a chance to reset. Who can do it?\""},{"type":"paragraph","content":"I looked at Ying first."},{"type":"paragraph","content":[{"type":"conditional","content":"She met my eyes. There was something steadier in her face than I expected. ","predicate":0}," ",{"type":"conditional","content":"She looked at the ground. Her jaw was tight. ","predicate":1},""]},{"type":"paragraph","content":"I looked at the substitute. She gave a small nod and said, \"I can go in.\""}],"stateDependencies":[{"type":"predicate","fn":{"$code":"return ((Q['comforted_pitcher'] || 0)===1);"}},{"type":"predicate","fn":{"$code":"return ((Q['comforted_pitcher'] || 0)===0);"}}]}},"root.choice2_rely":{"id":"root.choice2_rely","title":"The seniors will carry us","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@root.choice3_champion","title":"\"We are going to win the championship this year!\""},{"id":"@root.choice3_effort","title":"\"No matter who we face, we give everything we have.\""}],"content":[{"type":"paragraph","content":"\"Our seniors are strong. I'm confident we'll be fine.\""},{"type":"paragraph","content":"The seniors smiled. One of them waved it off. Another took the compliment and stood a little taller."},{"type":"paragraph","content":"Finally, I looked out at everyone and took a breath."},{"type":"paragraph","content":"\"Let's talk about our goal for this year.\""}]},"match_opening.choice_comfortable":{"id":"match_opening.choice_comfortable","title":"This is going exactly as planned","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@errors_begin","title":"Then the fourth inning came"}],"content":{"content":"I crossed my arms and watched, relaxed. The scoreboard said what it said. I had no reason to worry.","type":"paragraph"}},"root.choice2_cherish":{"id":"root.choice2_cherish","title":"Give them a beautiful farewell","options":[{"id":"@root.choice3_champion","title":"\"We are going to win the championship this year!\""},{"id":"@root.choice3_effort","title":"\"No matter who we face, we give everything we have.\""}],"content":[{"type":"paragraph","content":"\"I hope everyone will learn from them. Let's give the seniors the best farewell we can.\""},{"type":"paragraph","content":"As the words landed, one of the seniors lowered her head. I couldn't quite read her expression, but I thought she was smiling."},{"type":"paragraph","content":"Finally, I looked out at everyone and took a breath."},{"type":"paragraph","content":"\"Let's talk about our goal for this year.\""}]},"match_opening.choice_watchful":{"id":"match_opening.choice_watchful","title":"Stay sharp","options":[{"id":"@errors_begin","title":"Then the fourth inning came"}],"content":[{"type":"paragraph","content":"I kept my eyes moving — the fielders, the batter, the runners, the other bench. Looking for anything that might shift."},{"type":"paragraph","content":"Nothing did. Not yet."}]},"match_opening":{"id":"match_opening","type":"scene","title":"The Opening Innings","newPage":true,"options":[{"id":"@match_opening.choice_let_it_go","title":"Let it go. She is probably right."},{"id":"@match_opening.choice_stay_sharp","title":"Call her out. It is not done until it is done."}],"content":[{"type":"paragraph","content":"The first pitch was thrown and we came out strong."},{"type":"paragraph","content":"Our batters were connecting. Our fielding was clean. The East Asian Languages team looked exactly as I had expected — a little slow, a little uncertain. By the end of the second inning we were up three to nothing."},{"type":"paragraph","content":"The bench was loose and happy. People were talking between plays, laughing at small things."},{"type":"paragraph","content":"Then one of our players on the bench leaned back and said, loud enough for half the team to hear: \"This one's already done.\""}]},"root.choice3_champion":{"id":"root.choice3_champion","title":"Going for the championship","onArrival":[{"$code":"Q['overconfident'] = (Q['overconfident'] || 0) + 1;"}],"options":[{"id":"@daily_training","title":"The address was over."}],"content":[{"type":"paragraph","content":"\"We are going to win the championship this year!\""},{"type":"paragraph","content":"Someone started clapping. Cheers and laughter broke out, louder than I expected. I found myself smiling too."}]},"root.choice3_effort":{"id":"root.choice3_effort","title":"Give everything we have","options":[{"id":"@daily_training","title":"The address was over."}],"content":[{"type":"paragraph","content":"\"No matter who we face, we give everything we have.\""},{"type":"paragraph","content":"\"Yeah!\" A few voices rang out together."}]},"root":{"id":"root","type":"scene","title":"First Training Session","newPage":true,"options":[{"id":"@root.speech_result","title":"Begin the address"}],"content":[{"type":"paragraph","content":"It was the first training session of the new semester."},{"type":"paragraph","content":"The autumn breeze still carried a hint of summer's warmth. The grass on the field bore uneven marks from countless footsteps. Players drifted in one by one, standing in small clusters, chatting and laughing, waiting for me to speak."},{"type":"paragraph","content":"I looked out at them. The senior players stood relaxed at the back. The first and second years pressed forward at the front, their eyes carrying that particular mix of nerves and curiosity that newcomers always had."},{"type":"paragraph","content":"As the coach of this team, the first training speech of the semester was mine to give. I cleared my throat and began."}]}},"qualities":{},"qdisplays":{},"tagLookup":{}};